WITH RECURSIVE x15 AS (SELECT * FROM x19 WHERE 0 UNION SELECT * FROM x20) SELECT x7.x1, x7.x2, JSON_OBJECTAGG(x7.x2, x7.x1) OVER (ORDER BY x7.x2 DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS x4, x7.x2, SUM(x7.x2), SUM(DISTINCT LENGTH(x7.x1)) FROM v186790 AS x7 WHERE x7.x2 < '111' GROUP BY x7.x1, x7.x2, x7.x2 LIMIT 42